/// <reference path="../edge-runtime.d.ts" />
import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { executeAutomationFlowRuntime } from "../_shared/omnichannelFlow/graphExecutor.ts";
import { omnichannelFlowCorsHeaders, omnichannelFlowJson } from "../_shared/omnichannelFlow/omnichannelFlowAuth.ts";

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { status: 200, headers: omnichannelFlowCorsHeaders });
  }

  if (req.method !== "POST") {
    return omnichannelFlowJson({ error: "Method not allowed" }, 405);
  }

  try {
    const authHeader = req.headers.get("Authorization") ?? "";
    const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
    const token = authHeader.startsWith("Bearer ") ? authHeader.slice(7).trim() : "";
    if (!token || token !== serviceRoleKey) {
      return omnichannelFlowJson({ error: "Unauthorized" }, 401);
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
    const admin = createClient(supabaseUrl, serviceRoleKey);
    const body = await req.json().catch(() => ({}));

    await executeAutomationFlowRuntime(admin, {
      organizationId: String(body.organization_id ?? body.organizationId ?? ""),
      conversationId: String(body.conversation_id ?? body.conversationId ?? ""),
      messageId: String(body.message_id ?? body.messageId ?? ""),
      messageBody: String(body.message_body ?? body.messageBody ?? ""),
      phoneNumberId: body.phone_number_id ?? body.phoneNumberId ?? null,
      customerWaId: String(body.customer_wa_id ?? body.customerWaId ?? ""),
      customerName: body.customer_name ?? body.customerName ?? null,
      isResumeFromWait: Boolean(body.is_resume_from_wait ?? body.isResumeFromWait),
      replyId: body.reply_id ?? body.replyId ?? null,
    });

    return omnichannelFlowJson({ ok: true }, 200);
  } catch (err) {
    console.error("flow-runtime error:", err);
    return omnichannelFlowJson({ error: String(err) }, 500);
  }
});

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  evaluateConditionRules,
  matchesEnrollmentFilters,
  canEnroll,
} from "./enrollmentRules.ts";
import { delayToMs, interpolateContactVariables } from "./interpolateVariables.ts";
import {
  buildWhatsAppListInteractive,
  buildWhatsAppReplyButtonsInteractive,
  isInteractiveBranching,
  LIST_BRANCH_OTHER_HANDLE,
  normalizeSendMessageData,
  resolveListBranchHandle,
} from "./sendMessageRuntime.ts";
import { normalizeEndNodeData } from "./endNodeRuntime.ts";
import { sendFlowWhatsAppMessage } from "./flowRuntimeSendMessage.ts";

type GraphNode = {
  id: string;
  type: string;
  data?: Record<string, unknown>;
};

type GraphEdge = {
  id: string;
  source: string;
  target: string;
  sourceHandle?: string | null;
};

type Graph = {
  nodes?: GraphNode[];
  edges?: GraphEdge[];
};

export type RuntimeInbound = {
  organizationId: string;
  conversationId: string;
  messageId: string;
  messageBody: string;
  phoneNumberId: string | null;
  customerWaId: string;
  customerName?: string | null;
  isResumeFromWait?: boolean;
  replyId?: string | null;
};

async function logEvent(
  admin: SupabaseClient,
  orgId: string,
  flowId: string,
  enrollmentId: string | null,
  eventType: string,
  nodeId: string | null,
  payload: Record<string, unknown> = {},
): Promise<void> {
  await admin.from("omnichannel_flow_run_events").insert({
    organization_id: orgId,
    flow_id: flowId,
    enrollment_id: enrollmentId,
    event_type: eventType,
    node_id: nodeId,
    payload,
  });
}

function logEventAsync(
  admin: SupabaseClient,
  orgId: string,
  flowId: string,
  enrollmentId: string | null,
  eventType: string,
  nodeId: string | null,
  payload: Record<string, unknown> = {},
): void {
  void logEvent(admin, orgId, flowId, enrollmentId, eventType, nodeId, payload);
}

async function getConversationLabels(
  admin: SupabaseClient,
  conversationId: string,
): Promise<string[]> {
  const { data } = await admin
    .from("omnichannel_conversation_labels")
    .select("label_id, omnichannel_labels(name)")
    .eq("conversation_id", conversationId);
  const names: string[] = [];
  for (const row of data ?? []) {
    const labels = row as { omnichannel_labels?: { name?: string } | { name?: string }[] };
    const label = labels.omnichannel_labels;
    if (Array.isArray(label)) {
      for (const l of label) if (l?.name) names.push(String(l.name));
    } else if (label?.name) {
      names.push(String(label.name));
    }
  }
  return names;
}

function nextEdge(edges: GraphEdge[], nodeId: string, handle?: string | null): GraphEdge | null {
  const matches = edges.filter((e) => e.source === nodeId);
  if (handle) {
    const h = matches.find((e) => (e.sourceHandle ?? null) === handle);
    if (h) return h;
  }
  return matches[0] ?? null;
}

async function pickTeamAgent(
  admin: SupabaseClient,
  orgId: string,
  departmentId: string,
): Promise<string | null> {
  const { data: staffRows } = await admin
    .from("organization_omnichannel_staff")
    .select("employee_id, created_at, employees:employee_id(id, department_id)")
    .eq("organization_id", orgId)
    .order("created_at", { ascending: true });

  for (const row of staffRows ?? []) {
    const empRaw = (row as { employees?: { department_id?: string } | { department_id?: string }[] }).employees;
    const emp = Array.isArray(empRaw) ? empRaw[0] : empRaw;
    if (emp?.department_id && String(emp.department_id) === departmentId) {
      return String((row as { employee_id: string }).employee_id);
    }
  }
  return null;
}

function nodeById(nodes: GraphNode[], id: string): GraphNode | null {
  return nodes.find((n) => n.id === id) ?? null;
}

type FlowEnrollmentRow = {
  id: string;
  flow_id: string;
  organization_id: string;
  status: string;
  current_node_id: string | null;
  context_json: Record<string, unknown>;
  omnichannel_automation_flows: {
    published_graph_json: Graph | null;
    graph_json: Graph;
  };
};

async function findEnrollmentToResume(
  admin: SupabaseClient,
  conversationId: string,
): Promise<FlowEnrollmentRow | null> {
  const { data: rows } = await admin
    .from("omnichannel_flow_enrollments")
    .select("*, omnichannel_automation_flows(*)")
    .eq("conversation_id", conversationId)
    .in("status", ["waiting_for_reply", "active"])
    .order("updated_at", { ascending: false });

  for (const row of rows ?? []) {
    const enrollment = row as FlowEnrollmentRow;
    if (enrollment.status === "waiting_for_reply") return enrollment;

    const graph =
      enrollment.omnichannel_automation_flows.published_graph_json ??
      enrollment.omnichannel_automation_flows.graph_json;
    const currentNode = nodeById(graph.nodes ?? [], enrollment.current_node_id ?? "");
    if (currentNode?.type === "action_send_message" && isInteractiveBranching(currentNode.data ?? {})) {
      return enrollment;
    }
  }

  return null;
}

async function resumeInteractiveBranchReply(
  admin: SupabaseClient,
  args: {
    enrollment: FlowEnrollmentRow;
    inbound: RuntimeInbound;
    convCustomerName: string | null;
  },
): Promise<boolean> {
  const { enrollment, inbound, convCustomerName } = args;
  const graph =
    enrollment.omnichannel_automation_flows.published_graph_json ??
    enrollment.omnichannel_automation_flows.graph_json;
  const context = { ...(enrollment.context_json ?? {}) };
  context.last_customer_reply = inbound.messageBody;
  if (inbound.replyId) context.last_list_reply_id = inbound.replyId;
  context.last_list_reply_title = inbound.messageBody;

  const waitNode = nodeById(graph.nodes ?? [], enrollment.current_node_id ?? "");
  if (waitNode?.type !== "action_send_message" || !isInteractiveBranching(waitNode.data ?? {})) {
    return false;
  }

  const branchHandle = resolveListBranchHandle(
    waitNode.data ?? {},
    inbound.replyId ?? null,
    inbound.messageBody,
  );
  const edge = nextEdge(graph.edges ?? [], enrollment.current_node_id ?? "", branchHandle);

  if (!edge) {
    await admin
      .from("omnichannel_flow_enrollments")
      .update({
        status: "waiting_for_reply",
        context_json: context,
        updated_at: new Date().toISOString(),
      })
      .eq("id", enrollment.id);
    await logEvent(
      admin,
      enrollment.organization_id,
      enrollment.flow_id,
      enrollment.id,
      "branch_edge_missing",
      enrollment.current_node_id,
      { branchHandle, replyBody: inbound.messageBody, replyId: inbound.replyId },
    );
    console.error("flow branch edge missing", {
      enrollmentId: enrollment.id,
      nodeId: enrollment.current_node_id,
      branchHandle,
      replyBody: inbound.messageBody,
    });
    return true;
  }

  await admin
    .from("omnichannel_flow_enrollments")
    .update({
      status: "active",
      context_json: context,
      updated_at: new Date().toISOString(),
    })
    .eq("id", enrollment.id);

  await walkFromNode(admin, {
    graph,
    enrollmentId: enrollment.id,
    flowId: enrollment.flow_id,
    orgId: enrollment.organization_id,
    conversationId: inbound.conversationId,
    nodeId: edge.target,
    context,
    customerName: inbound.customerName ?? convCustomerName,
    customerWaId: inbound.customerWaId,
    phoneNumberId: inbound.phoneNumberId,
  });
  return true;
}

async function invokeFlowSend(
  admin: SupabaseClient,
  payload: Record<string, unknown>,
): Promise<{ ok: boolean; error?: string }> {
  const result = await sendFlowWhatsAppMessage(admin, payload as Parameters<typeof sendFlowWhatsAppMessage>[1]);
  return { ok: result.ok, error: result.error };
}

export async function executeAutomationFlowRuntime(
  admin: SupabaseClient,
  inbound: RuntimeInbound,
): Promise<void> {
  if (inbound.isResumeFromWait) {
    const [{ data: conv }, waitingEnrollment] = await Promise.all([
      admin
        .from("whatsapp_conversations")
        .select("assignee_id, customer_name")
        .eq("id", inbound.conversationId)
        .maybeSingle(),
      findEnrollmentToResume(admin, inbound.conversationId),
    ]);

    if (conv?.assignee_id) return;

    if (waitingEnrollment) {
      const flow = waitingEnrollment;
      const graph =
        flow.omnichannel_automation_flows.published_graph_json ??
        flow.omnichannel_automation_flows.graph_json;
      const waitNode = nodeById(graph.nodes ?? [], flow.current_node_id ?? "");
      if (waitNode?.type === "action_send_message" && isInteractiveBranching(waitNode.data ?? {})) {
        const handled = await resumeInteractiveBranchReply(admin, {
          enrollment: flow,
          inbound,
          convCustomerName: conv?.customer_name ?? null,
        });
        if (handled) return;
      }

      const context = { ...(flow.context_json ?? {}) };
      context.last_customer_reply = inbound.messageBody;
      if (inbound.replyId) context.last_list_reply_id = inbound.replyId;
      context.last_list_reply_title = inbound.messageBody;
      const saveVar = String(waitNode?.data?.saveAsVariable ?? "last_customer_reply");
      context[saveVar] = inbound.messageBody;

      await admin
        .from("omnichannel_flow_enrollments")
        .update({
          status: "active",
          context_json: context,
          updated_at: new Date().toISOString(),
        })
        .eq("id", waitingEnrollment.id);

      const edge = nextEdge(graph.edges ?? [], flow.current_node_id ?? "");
      if (edge) {
        await walkFromNode(admin, {
          graph,
          enrollmentId: waitingEnrollment.id,
          flowId: flow.flow_id,
          orgId: flow.organization_id,
          conversationId: inbound.conversationId,
          nodeId: edge.target,
          context,
          customerName: inbound.customerName ?? conv?.customer_name ?? null,
          customerWaId: inbound.customerWaId,
          phoneNumberId: inbound.phoneNumberId,
        });
      }
      return;
    }
  }

  const { data: conv } = await admin
    .from("whatsapp_conversations")
    .select("assignee_id, lead_status_id, customer_name, lead_statuses(name)")
    .eq("id", inbound.conversationId)
    .maybeSingle();

  if (conv?.assignee_id) {
    return;
  }

  let statusName: string | null = null;
  const ls = conv as { lead_statuses?: { name?: string } | { name?: string }[] };
  if (Array.isArray(ls.lead_statuses)) {
    statusName = ls.lead_statuses[0]?.name ?? null;
  } else {
    statusName = ls.lead_statuses?.name ?? null;
  }

  const labelNames = await getConversationLabels(admin, inbound.conversationId);
  const ctx = {
    messageBody: inbound.messageBody,
    conversationStatus: statusName,
    labelNames,
  };

  const { data: flows } = await admin
    .from("omnichannel_automation_flows")
    .select("*")
    .eq("organization_id", inbound.organizationId)
    .eq("status", "active");

  for (const flowRow of flows ?? []) {
    const flow = flowRow as {
      id: string;
      organization_id: string;
      re_enrollment_rule: string;
      trigger_config: Record<string, unknown>;
      published_graph_json: Graph | null;
      graph_json: Graph;
    };

    const graph = flow.published_graph_json ?? flow.graph_json;
    const start = (graph.nodes ?? []).find((n) => n.type === "start");
    if (!start) continue;

    const phoneIds = (start.data?.phoneNumberIds as string[] | undefined) ?? [];
    if (inbound.phoneNumberId && phoneIds.length > 0 && !phoneIds.includes(inbound.phoneNumberId)) {
      continue;
    }

    const enrollmentFilters = (start.data?.enrollmentFilters as unknown[]) ?? [];
    if (!matchesEnrollmentFilters(enrollmentFilters as never[], ctx)) continue;

    const { data: existingEnrollments } = await admin
      .from("omnichannel_flow_enrollments")
      .select("id, status")
      .eq("flow_id", flow.id)
      .eq("conversation_id", inbound.conversationId);

    const hasActive = (existingEnrollments ?? []).some((e) =>
      ["active", "waiting_for_reply"].includes(String((e as { status: string }).status))
    );
    const hasAny = (existingEnrollments ?? []).length > 0;
    if (!canEnroll(flow.re_enrollment_rule as never, hasActive, hasAny)) continue;

    const { data: enrollment, error: enrollErr } = await admin
      .from("omnichannel_flow_enrollments")
      .insert({
        organization_id: flow.organization_id,
        flow_id: flow.id,
        conversation_id: inbound.conversationId,
        channel: "whatsapp",
        status: "active",
        current_node_id: start.id,
        context_json: { last_customer_reply: inbound.messageBody },
      })
      .select("id")
      .single();

    if (enrollErr || !enrollment) continue;

    await logEvent(admin, flow.organization_id, flow.id, enrollment.id, "enrolled", start.id, {
      messageId: inbound.messageId,
    });

    const firstEdge = nextEdge(graph.edges ?? [], start.id);
    if (!firstEdge) continue;

    await walkFromNode(admin, {
      graph,
      enrollmentId: enrollment.id,
      flowId: flow.id,
      orgId: flow.organization_id,
      conversationId: inbound.conversationId,
      nodeId: firstEdge.target,
      context: { last_customer_reply: inbound.messageBody },
      customerName: inbound.customerName ?? conv?.customer_name ?? null,
      customerWaId: inbound.customerWaId,
      phoneNumberId: inbound.phoneNumberId,
    });
  }
}

type WalkArgs = {
  graph: Graph;
  enrollmentId: string;
  flowId: string;
  orgId: string;
  conversationId: string;
  nodeId: string;
  context: Record<string, unknown>;
  customerName: string | null;
  customerWaId: string;
  phoneNumberId: string | null;
};

async function walkFromNode(admin: SupabaseClient, args: WalkArgs): Promise<void> {
  let currentId: string | null = args.nodeId;
  let safety = 0;

  while (currentId && safety < 50) {
    safety += 1;
    const node = nodeById(args.graph.nodes ?? [], currentId);
    if (!node) break;

    if (node.type === "action_send_message") {
      const sendData = normalizeSendMessageData(node.data ?? {});
      const body = interpolateContactVariables(String(sendData.body ?? ""), {
        fullName: args.customerName,
        lastCustomerReply: String(args.context.last_customer_reply ?? ""),
      });

      const isList = sendData.buttonType === "list_message";
      const isQuickReply = sendData.buttonType === "quick_reply";
      const branching = isInteractiveBranching(node.data ?? {});

      const sendPayload: Record<string, unknown> = {
        organization_id: args.orgId,
        conversation_id: args.conversationId,
        enrollment_id: args.enrollmentId,
        flow_id: args.flowId,
        node_id: node.id,
        text: body,
        to: args.customerWaId,
      };
      if (args.phoneNumberId) sendPayload.phone_number_id = args.phoneNumberId;

      if (isList) {
        sendPayload.interactive = buildWhatsAppListInteractive(node.data ?? {}, body);
      } else if (isQuickReply) {
        sendPayload.interactive = buildWhatsAppReplyButtonsInteractive(node.data ?? {}, body);
      }

      const sendRes = await invokeFlowSend(admin, sendPayload);
      if (!sendRes.ok) {
        await admin
          .from("omnichannel_flow_enrollments")
          .update({ status: "failed", updated_at: new Date().toISOString() })
          .eq("id", args.enrollmentId);
        await logEvent(admin, args.orgId, args.flowId, args.enrollmentId, "send_failed", node.id, {
          error: sendRes.error,
        });
        break;
      }

      logEventAsync(admin, args.orgId, args.flowId, args.enrollmentId, "message_sent", node.id);

      if (branching) {
        await admin
          .from("omnichannel_flow_enrollments")
          .update({
            status: "waiting_for_reply",
            current_node_id: node.id,
            updated_at: new Date().toISOString(),
          })
          .eq("id", args.enrollmentId);
        logEventAsync(admin, args.orgId, args.flowId, args.enrollmentId, "waiting_for_reply", node.id, {
          listBranch: true,
        });
        break;
      }

      void admin
        .from("omnichannel_flow_enrollments")
        .update({ current_node_id: node.id, updated_at: new Date().toISOString() })
        .eq("id", args.enrollmentId);

      const edge = nextEdge(args.graph.edges ?? [], node.id);
      currentId = edge?.target ?? null;
      continue;
    }

    await admin
      .from("omnichannel_flow_enrollments")
      .update({ current_node_id: node.id, updated_at: new Date().toISOString() })
      .eq("id", args.enrollmentId);

    const { data: enrollCheck } = await admin
      .from("omnichannel_flow_enrollments")
      .select("status")
      .eq("id", args.enrollmentId)
      .maybeSingle();
    if (enrollCheck?.status === "paused") break;

    if (node.type === "end") {
      const endData = normalizeEndNodeData(node.data);
      if (endData.mode === "jump_to") {
        if (!endData.jumpToNodeId) {
          await logEvent(admin, args.orgId, args.flowId, args.enrollmentId, "jump_to_failed", node.id, {
            reason: "target_missing",
          });
          console.error("flow jump_to failed: target missing", {
            enrollmentId: args.enrollmentId,
            endNodeId: node.id,
          });
          await admin
            .from("omnichannel_flow_enrollments")
            .update({ status: "failed", updated_at: new Date().toISOString() })
            .eq("id", args.enrollmentId);
          break;
        }

        const target = (args.graph.nodes ?? []).find((n) => n.id === endData.jumpToNodeId);
        if (target && target.type !== "end" && target.type !== "start") {
          await admin
            .from("omnichannel_flow_enrollments")
            .update({
              status: "active",
              current_node_id: endData.jumpToNodeId,
              updated_at: new Date().toISOString(),
            })
            .eq("id", args.enrollmentId);
          await logEvent(admin, args.orgId, args.flowId, args.enrollmentId, "jump_to", node.id, {
            targetNodeId: endData.jumpToNodeId,
          });
          currentId = endData.jumpToNodeId;
          continue;
        }

        const reason = !target
          ? "target_not_found"
          : target.type === "end" || target.type === "start"
            ? "target_invalid_type"
            : "unknown";
        await logEvent(admin, args.orgId, args.flowId, args.enrollmentId, "jump_to_failed", node.id, {
          targetNodeId: endData.jumpToNodeId,
          reason,
        });
        console.error("flow jump_to failed", {
          enrollmentId: args.enrollmentId,
          endNodeId: node.id,
          targetNodeId: endData.jumpToNodeId,
          reason,
        });
        await admin
          .from("omnichannel_flow_enrollments")
          .update({ status: "failed", updated_at: new Date().toISOString() })
          .eq("id", args.enrollmentId);
        break;
      }

      await admin
        .from("omnichannel_flow_enrollments")
        .update({ status: "completed", updated_at: new Date().toISOString() })
        .eq("id", args.enrollmentId);
      await logEvent(admin, args.orgId, args.flowId, args.enrollmentId, "completed", node.id);
      break;
    }

    if (node.type === "condition") {
      const matchMode = (node.data?.matchMode as "all" | "any") ?? "all";
      const rules = (node.data?.rules as unknown[]) ?? [];
      const labelNames = await getConversationLabels(admin, args.conversationId);
      const passed = evaluateConditionRules(rules as never[], matchMode, {
        messageBody: String(args.context.last_customer_reply ?? ""),
        conversationStatus: null,
        labelNames,
      });
      const edge = nextEdge(args.graph.edges ?? [], node.id, passed ? "yes" : "no");
      currentId = edge?.target ?? null;
      continue;
    }

    if (node.type === "time_delay") {
      const duration = Number(node.data?.duration ?? 0);
      const unit = String(node.data?.unit ?? "minutes");
      const ms = delayToMs(duration, unit);
      const resumeAt = new Date(Date.now() + ms).toISOString();
      const edge = nextEdge(args.graph.edges ?? [], node.id);
      const targetNodeId = edge?.target ?? null;
      if (!targetNodeId) break;

      await admin.from("omnichannel_flow_delay_jobs").insert({
        enrollment_id: args.enrollmentId,
        organization_id: args.orgId,
        resume_at: resumeAt,
        target_node_id: targetNodeId,
        status: "pending",
      });
      await logEvent(admin, args.orgId, args.flowId, args.enrollmentId, "delay_scheduled", node.id, {
        resumeAt,
        targetNodeId,
      });
      break;
    }

    if (node.type === "action_wait_reply") {
      await admin
        .from("omnichannel_flow_enrollments")
        .update({
          status: "waiting_for_reply",
          current_node_id: node.id,
          updated_at: new Date().toISOString(),
        })
        .eq("id", args.enrollmentId);
      await logEvent(admin, args.orgId, args.flowId, args.enrollmentId, "waiting_for_reply", node.id);
      break;
    }

    if (node.type === "action_assign_to") {
      const mode = String(node.data?.assignMode ?? "specific_user");
      let assigneeId: string | null = null;
      const nowIso = new Date().toISOString();

      if (mode === "specific_user") {
        const empId = String(node.data?.employeeId ?? "").trim();
        assigneeId = empId || null;
      } else if (mode === "specific_team") {
        const deptId = String(node.data?.departmentId ?? "").trim();
        if (deptId) {
          assigneeId = await pickTeamAgent(admin, args.orgId, deptId);
        }
      }

      const { error: assignErr } = await admin
        .from("whatsapp_conversations")
        .update({ assignee_id: assigneeId, updated_at: nowIso })
        .eq("id", args.conversationId);

      if (assignErr) {
        await logEvent(admin, args.orgId, args.flowId, args.enrollmentId, "assign_failed", node.id, {
          error: assignErr.message,
        });
      } else {
        await logEvent(admin, args.orgId, args.flowId, args.enrollmentId, "conversation_assigned", node.id, {
          assigneeId,
          mode,
        });
      }

      if (assigneeId) {
        break;
      }
      const assignEdge = nextEdge(args.graph.edges ?? [], node.id);
      currentId = assignEdge?.target ?? null;
      continue;
    }

    if (node.type === "action_update_contact") {
      const leadStatusId = node.data?.leadStatusId as string | null | undefined;
      const category = node.data?.category as string | null | undefined;
      const services = node.data?.services as string | null | undefined;
      const convUpdate: Record<string, unknown> = { updated_at: new Date().toISOString() };
      if (leadStatusId) convUpdate.lead_status_id = leadStatusId;
      await admin.from("whatsapp_conversations").update(convUpdate).eq("id", args.conversationId);

      const { data: convRow } = await admin
        .from("whatsapp_conversations")
        .select("ticket_id")
        .eq("id", args.conversationId)
        .maybeSingle();
      if (convRow?.ticket_id && (category || services)) {
        const leadUpdate: Record<string, unknown> = { updated_at: new Date().toISOString() };
        if (category) leadUpdate.category = category;
        if (services) leadUpdate.services = services;
        await admin.from("leads").update(leadUpdate).eq("ticket_id", convRow.ticket_id);
      }
      await logEvent(admin, args.orgId, args.flowId, args.enrollmentId, "contact_updated", node.id);
      const edge = nextEdge(args.graph.edges ?? [], node.id);
      currentId = edge?.target ?? null;
      continue;
    }

    if (node.type === "action_http_request") {
      const url = String(node.data?.url ?? "").trim();
      const method = String(node.data?.method ?? "POST").toUpperCase();
      const bodyTemplate = String(node.data?.bodyTemplate ?? "");
      const body = interpolateContactVariables(bodyTemplate, {
        fullName: args.customerName,
        lastCustomerReply: String(args.context.last_customer_reply ?? ""),
      });
      try {
        if (url) {
          await fetch(url, {
            method,
            headers: { "Content-Type": "application/json" },
            body: method === "GET" ? undefined : body,
          });
        }
        await logEvent(admin, args.orgId, args.flowId, args.enrollmentId, "http_request", node.id, { url });
      } catch (err) {
        await logEvent(admin, args.orgId, args.flowId, args.enrollmentId, "http_request_failed", node.id, {
          error: String(err),
        });
      }
      const edge = nextEdge(args.graph.edges ?? [], node.id);
      currentId = edge?.target ?? null;
      continue;
    }

    const edge = nextEdge(args.graph.edges ?? [], node.id);
    currentId = edge?.target ?? null;
  }
}

export async function resumeEnrollmentFromDelayJob(
  admin: SupabaseClient,
  jobId: string,
): Promise<void> {
  const { data: job } = await admin
    .from("omnichannel_flow_delay_jobs")
    .select("*, omnichannel_flow_enrollments(*, omnichannel_automation_flows(*))")
    .eq("id", jobId)
    .maybeSingle();

  if (!job) return;

  const row = job as {
    id: string;
    target_node_id: string;
    status: string;
    omnichannel_flow_enrollments: {
      id: string;
      flow_id: string;
      organization_id: string;
      conversation_id: string;
      status: string;
      context_json: Record<string, unknown>;
      omnichannel_automation_flows: {
        published_graph_json: Graph | null;
        graph_json: Graph;
      };
    };
  };

  if (row.status !== "processing" && row.status !== "pending") return;
  const enrollment = row.omnichannel_flow_enrollments;
  if (!enrollment || enrollment.status === "paused") {
    await admin.from("omnichannel_flow_delay_jobs").update({ status: "done" }).eq("id", jobId);
    return;
  }

  const { data: conv } = await admin
    .from("whatsapp_conversations")
    .select("customer_name, customer_wa_id, assignee_id, phone_number_id")
    .eq("id", enrollment.conversation_id)
    .maybeSingle();

  if (conv?.assignee_id) {
    await admin.from("omnichannel_flow_delay_jobs").update({ status: "done" }).eq("id", jobId);
    return;
  }

  const graph =
    enrollment.omnichannel_automation_flows.published_graph_json ??
    enrollment.omnichannel_automation_flows.graph_json;

  await walkFromNode(admin, {
    graph,
    enrollmentId: enrollment.id,
    flowId: enrollment.flow_id,
    orgId: enrollment.organization_id,
    conversationId: enrollment.conversation_id,
    nodeId: row.target_node_id,
    context: enrollment.context_json ?? {},
    customerName: conv?.customer_name ?? null,
    customerWaId: conv?.customer_wa_id ?? "",
    phoneNumberId: (conv?.phone_number_id as string | null) ?? null,
  });

  await admin
    .from("omnichannel_flow_delay_jobs")
    .update({ status: "done", updated_at: new Date().toISOString() })
    .eq("id", jobId);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

const META_API_BASE = "https://graph.facebook.com/v18.0";

export type FlowWhatsAppSendPayload = {
  organization_id?: string;
  conversation_id: string;
  enrollment_id?: string;
  flow_id?: string;
  node_id?: string;
  text?: string;
  to?: string;
  phone_number_id?: string;
  interactive?: Record<string, unknown>;
};

export async function sendFlowWhatsAppMessage(
  admin: SupabaseClient,
  body: FlowWhatsAppSendPayload,
): Promise<{ ok: boolean; error?: string; waMessageId?: string | null }> {
  const organizationId = String(body.organization_id ?? "");
  const conversationId = String(body.conversation_id ?? "");
  const enrollmentId = String(body.enrollment_id ?? "");
  const flowId = String(body.flow_id ?? "");
  const text = String(body.text ?? "").trim();
  const interactive = body.interactive;
  let to = String(body.to ?? "").replace(/\D/g, "");
  const presetPhoneNumberId = String(body.phone_number_id ?? "").trim() || null;

  if (!conversationId || (!text && !interactive)) {
    return { ok: false, error: "conversation_id and text or interactive required" };
  }

  let orgId = organizationId;
  let phoneNumberId = presetPhoneNumberId;

  if (!orgId || !phoneNumberId || !to) {
    const { data: conv } = await admin
      .from("whatsapp_conversations")
      .select("organization_id, phone_number_id, customer_wa_id, channel")
      .eq("id", conversationId)
      .maybeSingle();

    if (!conv) return { ok: false, error: "Conversation not found" };
    if ((conv.channel ?? "whatsapp").toLowerCase() === "instagram") {
      return { ok: false, error: "Instagram not supported" };
    }

    orgId = orgId || (conv.organization_id as string);
    if (!phoneNumberId) phoneNumberId = (conv.phone_number_id as string | null) ?? null;
    if (!to) to = String(conv.customer_wa_id ?? "").replace(/\D/g, "");
  } else if (!orgId) {
    return { ok: false, error: "organization_id required when phone_number_id is preset" };
  }

  const tryAccount = async (oid: string, pnId: string | null) => {
    const base = admin
      .from("organization_whatsapp_accounts")
      .select("meta_access_token, phone_number_id")
      .eq("organization_id", oid)
      .eq("is_active", true);
    const q = pnId ? base.eq("phone_number_id", pnId) : base.limit(1);
    const { data: rows } = await q;
    const data = Array.isArray(rows) ? rows[0] : null;
    if (!data?.phone_number_id) return null;
    let accessToken = String(data.meta_access_token ?? "").trim();
    if (!accessToken) {
      const { data: orgMeta } = await admin
        .from("organization_meta_config")
        .select("meta_access_token")
        .eq("organization_id", oid)
        .maybeSingle();
      accessToken = String(orgMeta?.meta_access_token ?? "").trim();
    }
    if (!accessToken) return null;
    return { meta_access_token: accessToken, phone_number_id: data.phone_number_id };
  };

  const config = await tryAccount(orgId, phoneNumberId);
  if (!config) {
    return { ok: false, error: "WhatsApp account not configured" };
  }

  const metaUrl = `${META_API_BASE}/${config.phone_number_id}/messages`;
  const interactiveType = String(interactive?.type ?? "");
  const isInteractive = interactiveType === "list" || interactiveType === "button";
  const metaBody = isInteractive
    ? {
        messaging_product: "whatsapp",
        to,
        type: "interactive",
        interactive,
      }
    : {
        messaging_product: "whatsapp",
        to,
        type: "text",
        text: { body: text },
      };

  const metaRes = await fetch(metaUrl, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${config.meta_access_token}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(metaBody),
  });

  const metaData = await metaRes.json().catch(() => ({}));
  if (!metaRes.ok) {
    return {
      ok: false,
      error: String(metaData?.error?.message ?? "Meta API error"),
    };
  }

  const waMessageId = metaData.messages?.[0]?.id ?? null;
  const now = new Date().toISOString();

  let storedBody = text;
  let messageType = "text";
  if (isInteractive && interactive) {
    if (interactiveType === "list") {
      const buttonText = String((interactive as { action?: { button?: string } }).action?.button ?? "Pilih Opsi");
      const rows = (interactive as { action?: { sections?: Array<{ rows?: unknown[] }> } }).action?.sections?.[0]?.rows ?? [];
      storedBody = `${text}\n\n[${buttonText} · ${rows.length} option(s)]`;
    } else if (interactiveType === "button") {
      const buttons = (interactive as { action?: { buttons?: Array<{ reply?: { title?: string } }> } }).action?.buttons ?? [];
      const labels = buttons.map((b) => b.reply?.title).filter(Boolean).join(", ");
      storedBody = labels ? `${text}\n\n[${labels}]` : text;
    }
    messageType = "interactive";
  }

  const insertPayload: Record<string, unknown> = {
    conversation_id: conversationId,
    direction: "outbound",
    wa_message_id: waMessageId,
    platform_message_id: waMessageId,
    channel: "whatsapp",
    body: storedBody,
    message_type: messageType,
    raw_metadata: { ...metaData, flow_interactive: interactive ?? null },
    status: "sent",
    source: "flow_automation",
    automation_flow_id: flowId || null,
    automation_enrollment_id: enrollmentId || null,
  };

  void admin.from("whatsapp_messages").insert(insertPayload).then(({ error }) => {
    if (error) console.error("flow send insert error:", error);
  });
  void admin.rpc("sync_conversation_last_message", { p_conversation_id: conversationId });
  void admin
    .from("whatsapp_conversations")
    .update({ last_message_at: now, updated_at: now })
    .eq("id", conversationId);

  return { ok: true, waMessageId };
}

export type ListMessageOption = {
  id: string;
  title: string;
  description?: string;
};

export type SendMessageNodeData = {
  body?: string;
  buttonType?: string;
  listButtonText?: string;
  listSectionTitle?: string;
  listOptions?: ListMessageOption[];
  buttonAsBranch?: boolean;
};

export const LIST_BRANCH_OTHER_HANDLE = "option:other";

export const QUICK_REPLY_LIMITS = {
  maxButtons: 3,
  titleMax: 20,
} as const;

export function normalizeSendMessageData(data: Record<string, unknown> | undefined): Required<
  Pick<SendMessageNodeData, "body" | "buttonType" | "buttonAsBranch">
> & {
  listButtonText?: string;
  listSectionTitle?: string;
  listOptions: ListMessageOption[];
} {
  const rawOptions = Array.isArray(data?.listOptions) ? data!.listOptions : [];
  const listOptions: ListMessageOption[] = rawOptions
    .filter((item): item is Record<string, unknown> => Boolean(item) && typeof item === "object")
    .map((item, index) => ({
      id: String(item.id ?? `opt-${index + 1}`),
      title: String(item.title ?? ""),
      description: item.description ? String(item.description) : undefined,
    }));

  const buttonType = String(data?.buttonType ?? "none");
  return {
    body: String(data?.body ?? ""),
    buttonType: buttonType === "list_message" ? "list_message" : buttonType === "quick_reply" ? "quick_reply" : "none",
    listButtonText: data?.listButtonText ? String(data.listButtonText) : undefined,
    listSectionTitle: data?.listSectionTitle ? String(data.listSectionTitle) : undefined,
    listOptions,
    buttonAsBranch:
      (buttonType === "list_message" || buttonType === "quick_reply") && listOptions.length > 0
        ? true
        : Boolean(data?.buttonAsBranch),
  };
}

export function isListMessageBranching(data: SendMessageNodeData | Record<string, unknown>): boolean {
  const normalized = normalizeSendMessageData(data as Record<string, unknown>);
  return normalized.buttonType === "list_message" && normalized.listOptions.length > 0;
}

export function isQuickReplyBranching(data: SendMessageNodeData | Record<string, unknown>): boolean {
  const normalized = normalizeSendMessageData(data as Record<string, unknown>);
  return normalized.buttonType === "quick_reply" && normalized.listOptions.length > 0;
}

export function isInteractiveBranching(data: SendMessageNodeData | Record<string, unknown>): boolean {
  return isListMessageBranching(data) || isQuickReplyBranching(data);
}

export function getInteractiveBranchHandles(data: SendMessageNodeData | Record<string, unknown>): string[] {
  const normalized = normalizeSendMessageData(data as Record<string, unknown>);
  if (!isInteractiveBranching(normalized)) return [];
  const optionHandles = (normalized.listOptions ?? []).map((opt) => `option:${opt.id}`);
  return [...optionHandles, LIST_BRANCH_OTHER_HANDLE];
}

export function buildWhatsAppListInteractive(data: SendMessageNodeData | Record<string, unknown>, bodyText: string) {
  const normalized = normalizeSendMessageData(data as Record<string, unknown>);
  const rows = (normalized.listOptions ?? []).map((opt) => ({
    id: opt.id,
    title: opt.title.slice(0, 24),
    ...(opt.description ? { description: opt.description.slice(0, 72) } : {}),
  }));

  return {
    type: "list",
    body: { text: bodyText },
    action: {
      button: String(normalized.listButtonText ?? "Pilih Opsi").slice(0, 20),
      sections: [
        {
          ...(normalized.listSectionTitle ? { title: normalized.listSectionTitle.slice(0, 24) } : {}),
          rows,
        },
      ],
    },
  };
}

export function buildWhatsAppReplyButtonsInteractive(
  data: SendMessageNodeData | Record<string, unknown>,
  bodyText: string,
) {
  const normalized = normalizeSendMessageData(data as Record<string, unknown>);
  const options = (normalized.listOptions ?? []).slice(0, QUICK_REPLY_LIMITS.maxButtons);
  return {
    type: "button",
    body: { text: bodyText.slice(0, 1024) },
    action: {
      buttons: options.map((opt) => ({
        type: "reply",
        reply: {
          id: opt.id,
          title: opt.title.slice(0, QUICK_REPLY_LIMITS.titleMax),
        },
      })),
    },
  };
}

export function resolveListBranchHandle(
  nodeData: Record<string, unknown>,
  replyId: string | null,
  replyTitle: string,
): string {
  const normalized = normalizeSendMessageData(nodeData);
  const options = normalized.listOptions ?? [];
  if (replyId) {
    const byId = options.find((opt) => opt.id === replyId);
    if (byId) return `option:${byId.id}`;
  }
  const titleNorm = replyTitle.trim().toLowerCase();
  const byTitle = options.find((opt) => opt.title.trim().toLowerCase() === titleNorm);
  if (byTitle) return `option:${byTitle.id}`;
  return LIST_BRANCH_OTHER_HANDLE;
}

export function extractInboundWhatsAppBody(msg: Record<string, unknown>): {
  body: string;
  messageType: string;
  replyId: string | null;
} {
  const msgType = String(msg.type ?? "text");
  if (msgType === "interactive") {
    const interactive = msg.interactive as Record<string, unknown> | undefined;
    const listReply = interactive?.list_reply as { id?: string; title?: string } | undefined;
    if (listReply?.title || listReply?.id) {
      return {
        body: String(listReply.title ?? listReply.id ?? ""),
        messageType: "list_reply",
        replyId: listReply.id ? String(listReply.id) : null,
      };
    }
    const buttonReply = interactive?.button_reply as { id?: string; title?: string } | undefined;
    if (buttonReply?.title || buttonReply?.id) {
      return {
        body: String(buttonReply.title ?? buttonReply.id ?? ""),
        messageType: "button_reply",
        replyId: buttonReply.id ? String(buttonReply.id) : null,
      };
    }
  }
  const textBody = (msg.text as { body?: string } | undefined)?.body;
  return {
    body: textBody ?? `[${msgType}]`,
    messageType: msgType,
    replyId: null,
  };
}

export type AutomationFlowEndMode = "flow_end" | "jump_to";

export type NormalizedEndNodeData = {
  mode: AutomationFlowEndMode;
  jumpToNodeId: string | null;
};

export function normalizeEndNodeData(data: Record<string, unknown> | undefined): NormalizedEndNodeData {
  const mode = (data?.mode as AutomationFlowEndMode | undefined) ?? "flow_end";
  const jumpToNodeId =
    mode === "jump_to" && typeof data?.jumpToNodeId === "string" && data.jumpToNodeId.trim()
      ? data.jumpToNodeId.trim()
      : null;

  return {
    mode,
    jumpToNodeId: mode === "jump_to" ? jumpToNodeId : null,
  };
}

type ConditionRule = {
  field?: string;
  operator?: string;
  value?: string;
};

type EnrollmentContext = {
  messageBody?: string;
  conversationStatus?: string | null;
  labelNames?: string[];
};

function matchRule(rule: ConditionRule, ctx: EnrollmentContext): boolean {
  const field = String(rule.field ?? "");
  const operator = String(rule.operator ?? "contains");
  const value = String(rule.value ?? "").trim().toLowerCase();

  let actual = "";
  if (field === "keyword") actual = (ctx.messageBody ?? "").toLowerCase();
  else if (field === "conversation_status") actual = (ctx.conversationStatus ?? "").toLowerCase();
  else if (field === "label") {
    const labels = (ctx.labelNames ?? []).map((l) => l.toLowerCase());
    if (operator === "contains") return labels.some((l) => l.includes(value));
    if (operator === "equals") return labels.includes(value);
    if (operator === "not_equals") return !labels.includes(value);
    if (operator === "is_empty") return labels.length === 0;
    if (operator === "is_not_empty") return labels.length > 0;
    return false;
  }

  if (operator === "contains") return actual.includes(value);
  if (operator === "equals") return actual === value;
  if (operator === "not_equals") return actual !== value;
  if (operator === "is_empty") return actual.length === 0;
  if (operator === "is_not_empty") return actual.length > 0;
  return false;
}

export function evaluateConditionRules(
  rules: ConditionRule[],
  matchMode: "all" | "any",
  ctx: EnrollmentContext,
): boolean {
  if (!rules.length) return true;
  if (matchMode === "any") return rules.some((r) => matchRule(r, ctx));
  return rules.every((r) => matchRule(r, ctx));
}

export function matchesEnrollmentFilters(
  filters: ConditionRule[],
  ctx: EnrollmentContext,
): boolean {
  if (!filters.length) return true;
  return evaluateConditionRules(filters, "all", ctx);
}

export type ReEnrollmentRule = "not_in_flow" | "never" | "always";

export function canEnroll(
  rule: ReEnrollmentRule,
  hasActiveEnrollment: boolean,
  hasAnyPastEnrollment: boolean,
): boolean {
  if (rule === "always") return true;
  if (rule === "never") return !hasAnyPastEnrollment;
  return !hasActiveEnrollment;
}

export function interpolateContactVariables(
  template: string,
  context: {
    firstName?: string | null;
    lastName?: string | null;
    fullName?: string | null;
    lastCustomerReply?: string | null;
  },
): string {
  const firstName =
    context.firstName?.trim() ||
    context.fullName?.trim()?.split(/\s+/)[0] ||
    "";
  const lastName = context.lastName?.trim() || "";
  const fullName = context.fullName?.trim() || firstName;
  const lastReply = context.lastCustomerReply?.trim() || "";

  return template
    .replace(/\{\{\s*contact\.first_name\s*\}\}/gi, firstName)
    .replace(/\{\{\s*contact\.last_name\s*\}\}/gi, lastName)
    .replace(/\{\{\s*contact\.full_name\s*\}\}/gi, fullName)
    .replace(/\{\{\s*last_customer_reply\s*\}\}/gi, lastReply);
}

export function delayToMs(duration: number, unit: string): number {
  const d = Number(duration);
  if (!Number.isFinite(d) || d <= 0) return 0;
  if (unit === "hours") return d * 60 * 60 * 1000;
  if (unit === "days") return d * 24 * 60 * 60 * 1000;
  return d * 60 * 1000;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export const omnichannelFlowCorsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, PATCH, DELETE, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

export function omnichannelFlowJson(body: object, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...omnichannelFlowCorsHeaders, "Content-Type": "application/json" },
  });
}

export async function getUserFromBearer(
  admin: SupabaseClient,
  authHeader: string | null,
): Promise<{ userId: string } | { error: Response }> {
  const token = authHeader?.startsWith("Bearer ") ? authHeader.slice("Bearer ".length).trim() : "";
  if (!token) return { error: omnichannelFlowJson({ error: "Unauthorized" }, 401) };
  const { data: userRes, error: userErr } = await admin.auth.getUser(token);
  if (userErr || !userRes?.user?.id) {
    return { error: omnichannelFlowJson({ error: "Invalid token" }, 401) };
  }
  return { userId: userRes.user.id };
}

export async function isOmnichannelFlowAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<boolean> {
  const { data: owner } = await admin
    .from("user_roles")
    .select("id")
    .eq("user_id", userId)
    .eq("organization_id", organizationId)
    .eq("role", "owner")
    .maybeSingle();
  if (owner) return true;

  const { data: staffRows } = await admin
    .from("organization_omnichannel_staff")
    .select("employee_id, employees!inner(user_id)")
    .eq("organization_id", organizationId)
    .eq("role", "admin");

  for (const row of staffRows ?? []) {
    const emp = row as { employees?: { user_id?: string } | { user_id?: string }[] };
    const employees = emp.employees;
    const userIds: string[] = [];
    if (Array.isArray(employees)) {
      for (const e of employees) {
        if (e?.user_id) userIds.push(String(e.user_id));
      }
    } else if (employees && typeof employees === "object" && "user_id" in employees) {
      const uid = (employees as { user_id?: string }).user_id;
      if (uid) userIds.push(String(uid));
    }
    if (userIds.includes(userId)) return true;
  }
  return false;
}

export async function requireOmnichannelFlowAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const ok = await isOmnichannelFlowAdmin(admin, userId, organizationId);
  if (!ok) return omnichannelFlowJson({ error: "Forbidden", code: "ADMIN_REQUIRED" }, 403);
  return null;
}

export async function resolveEmployeeIdForUser(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<string | null> {
  const { data } = await admin
    .from("employees")
    .select("id")
    .eq("user_id", userId)
    .eq("organization_id", organizationId)
    .maybeSingle();
  return (data?.id as string | undefined) ?? null;
}
